BEGIN READ ONLY;SET LOCAL statement_timeout='10s';SELECT jsonb_build_object('role',current_user,'db',current_database(),'readOnly',current_setting('transaction_read_only'),'roles',(SELECT jsonb_agg(jsonb_build_object('name',r.rolname,'super',r.rolsuper,'inherit',r.rolinherit,'canLogin',r.rolcanlogin,'ownerMember',pg_has_role(r.oid,'postgres','MEMBER'),'canSetOwner',pg_has_role(r.oid,'postgres','SET'),'ownerUsage',pg_has_role(r.oid,'postgres','USAGE'),'canSetCli',pg_has_role(r.oid,'cli_login_postgres','SET'),'cliMember',pg_has_role(r.oid,'cli_login_postgres','MEMBER'))) FROM pg_roles r WHERE r.rolname IN('postgres','cli_login_postgres','authenticator','anon','authenticated','service_role')),'memberships',(SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(roleid),'member',pg_get_userbyid(member),'inherit',inherit_option,'set',set_option)) FROM pg_auth_members WHERE roleid IN('postgres'::regrole,'cli_login_postgres'::regrole))) metadata;ROLLBACK;